// Genereras av kallor-biologi/omrade1/exportsite.py – ändra inte för hand.
// Biologi område 1: varje moment finns i tre nivåer (lättläst, grundtext, fördjupning). Elevversion, utan facit.
var innehall = window.innehall || {};
innehall["biologi-m-1-1-1"] = {nivaer: {"lattlast": "<section class=\"sec m1\"><div class=\"lp\"><span class=\"p1\">LÄS</span><span class=\"t\">Start · Vad är biologi?</span><span class=\"dots\"><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">Vad är biologi?</h2><div class=\"t\"><p>Biologi är läran om allt som lever.</p><p>Allt som lever kallas <strong>organismer</strong>. Djur, växter, svampar och bakterier är organismer.</p><p>Biologer forskar om organismer. De forskar också om människans kropp.</p><p>Det finns många sorters biologer. Här är fyra:</p><div class=\"fig\"><img src=\"bilder/biologi-omrade1/l_yrken.png\"></div><p>Biologer arbetar ute i naturen eller inne i ett labb.</p><p>Många biologer hjälper till att skydda naturen eller att göra nya mediciner.</p></div><div class=\"kom\"><span class=\"ex\">!</span><div><span class=\"lb\">KOM IHÅG</span><span class=\"tx\">Biologi är läran om allt som lever. Allt som lever kallas organismer.</span></div></div></section><section class=\"sec m1\"><div class=\"lp\"><span class=\"p1 ova\">ÖVA</span><span class=\"t\">Start · Vad är biologi?</span><span class=\"dots\"><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">Öva: Vad är biologi?</h2><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">1</span><div><span class=\"ty\">RINGA IN</span><span class=\"q\">Vad är en organism?</span><div class=\"chips\"><span>Allt som lever</span><span>En sten</span><span>Ett tal</span></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">2</span><div><span class=\"ty\">DRA STRECK</span><span class=\"q\">Vad forskar biologerna om? Dra streck.</span><div class=\"dr\"><div>Zoolog</div><div>växter</div><div>Botaniker</div><div>små organismer, som bakterier</div><div>Marinbiolog</div><div>djur</div><div>Mikrobiolog</div><div>livet i havet</div></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">3</span><div><span class=\"ty\">FYLL I</span><span class=\"q\">Skriv rätt ord på linjen.</span><span class=\"bank\">Ord att välja: labb · naturen · kropp</span><div class=\"fy\"><p>Biologer kan arbeta ute i ______________.</p><p>Biologer kan också arbeta inne i ett ______________.</p><p>Biologer forskar också om människans ______________.</p></div></div></div></div></section><section class=\"sec m2\"><div class=\"lp\"><span class=\"p1\">LÄS</span><span class=\"t\">Delområde 1.1 · Moment 1.1.1</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">1.1.1 Från fråga till plan</h2><div class=\"t\"><p>Forskare börjar med en fråga. Men alla frågor går inte att undersöka.</p><p>En fråga som går att undersöka kallas en <strong>undersökningsbar fråga</strong>. Man kan svara på den genom att <strong>mäta</strong> eller <strong>titta</strong>.</p><table class=\"tb\"><tr><th>Går inte att undersöka</th><th>Går att undersöka</th></tr><tr><td>Är solrosor fina?</td><td>Hur mycket växer en solros på en vecka?</td></tr><tr><td>Är musik bra när man pluggar?</td><td>Kommer man ihåg fler ord efter att ha lyssnat på musik?</td></tr></table><p>Sedan gissar forskaren vad svaret blir. Det kallas en <strong>hypotes</strong>. Man skriver också varför man tror det.</p><p>Forskare arbetar i steg. Stegen går runt i en cirkel.</p><div class=\"fig\"><img src=\"bilder/biologi-omrade1/l_cykel.png\"></div><p><span class='fake'>Påhittat exempel</span> Ella undrar: <em>Växer krasse bättre i ljus eller i mörker?</em></p><p>Hypotes: <em>Krassen blir högst i ljus, eftersom växter behöver ljus.</em></p><div class=\"fig\" style=\"width:70%\"><img src=\"bilder/biologi-omrade1/l_krasse.png\"></div><p>Hon gör ett <strong>rättvist test</strong> med två lådor.</p><p>Ella ändrar bara en sak: ljuset. Allt annat är lika. Det man ändrar kallas en <strong>variabel</strong>.</p><table class=\"tb\"><tr><th>Ella ändrar</th><th>Ella mäter</th><th>Ella håller lika</th></tr><tr><td>ljuset (ljus eller mörker)</td><td>hur hög krassen blir (mm)</td><td>jord, vatten, antal frön</td></tr></table><h3>Säkert i labbet</h3><p>Läs hela instruktionen först. Ha skyddsglasögon när läraren säger det. Ät och drick aldrig i labbet. Fråga om du är osäker.</p></div><div class=\"kom\"><span class=\"ex\">!</span><div><span class=\"lb\">KOM IHÅG</span><span class=\"tx\">En fråga som går att undersöka kan man mäta. I ett rättvist test ändrar man bara en sak.</span></div></div></section><section class=\"sec m2\"><div class=\"lp\"><span class=\"p1 ova\">ÖVA</span><span class=\"t\">Delområde 1.1 · Moment 1.1.1</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">Öva: 1.1.1 Från fråga till plan</h2><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">1</span><div><span class=\"ty\">RINGA IN</span><span class=\"q\">Vilken fråga går att undersöka?</span><div class=\"chips\"><span>Är hundar snälla?</span><span>Hur långt hoppar en groda?</span><span>Är sommar bäst?</span></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">2</span><div><span class=\"ty\">DRA STRECK</span><span class=\"q\">Dra streck till rätt förklaring.</span><div class=\"dr\"><div>Det Ella ändrar</div><div>hur hög krassen blir</div><div>Det Ella mäter</div><div>jord och vatten</div><div>Det som är lika</div><div>ljuset</div></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">3</span><div><span class=\"ty\">KRYSSA</span><span class=\"q\">Vad ska vara lika i båda lådorna? Kryssa i rätt rutor.</span><div class=\"dr\"><div><b class='bx2'></b> Samma jord</div><div><b class='bx2'></b> Lika mycket vatten</div><div><b class='bx2'></b> Samma ljus</div><div><b class='bx2'></b> Lika många frön</div></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">4</span><div><span class=\"ty\">KRYSSA</span><span class=\"q\">Vad gör du i labbet? Kryssa i rätt rutor.</span><div class=\"dr\"><div><b class='bx2'></b> Läser hela instruktionen först</div><div><b class='bx2'></b> Äter godis</div><div><b class='bx2'></b> Frågar om jag är osäker</div><div><b class='bx2'></b> Springer runt</div></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">5</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Varför ska man bara ändra en sak i ett test?</span><div class=\"ln\">Man ska bara ändra en sak eftersom<i></i><i></i></div></div></div></div></section>", "vanlig": "<h3>Vad är biologi?</h3><div class=\"row\"><div class=\"main\"><p>Biologi betyder ”läran om livet”. Ordet kommer från grekiskans <em>bios</em> (liv) och <em>logos</em> (lära). Biologi handlar om allt som lever: bakterier, svampar, växter, djur och människor. Allt levande kallas <strong class='green'>organismer</strong>. Biologer undersöker hur organismer är uppbyggda, hur de fungerar, hur de samspelar med varandra och hur livet har utvecklats.</p><p>Biologi är en av <strong class='green'>naturvetenskaperna</strong>, tillsammans med bland annat kemi och fysik. Gemensamt för dem är att de försöker förklara naturen med hjälp av <strong class='green'>systematiska undersökningar</strong>: undersökningar som görs noggrant och planerat, så att andra kan kontrollera och upprepa dem.</p><h3>Biologer arbetar på många sätt</h3><p>Livet är så stort att ingen kan vara expert på allt. Därför specialiserar sig biologer. Vissa arbetar ute i naturen, andra i laboratorier, på sjukhus eller vid en dator där de analyserar stora mängder data.</p></div><div class=\"side\"><div class=\"bx begrepp\"><span class=\"rb\">Begrepp</span><b class=\"t\">Biologi</b><p>Läran om livet och levande organismer.</p><b class=\"t\">Organism</b><p>En levande varelse, till exempel en bakterie, en svamp, en växt eller ett djur.</p><b class=\"t\">Naturvetenskap</b><p>Vetenskaper som undersöker naturen, t.ex. biologi, kemi och fysik.</p></div></div></div><div class=\"fig\" style=\"width:82%\"><img src=\"bilder/biologi-omrade1/l_yrken.png\"><div class=\"cap\"><b>Bild 1.1</b> Fyra sorters biologer: zoolog (djur), botaniker (växter), mikrobiolog (små organismer) och marinbiolog (livet i havet).</div></div><div class=\"kolla\"><span class=\"kr\">Kolla dig själv Start</span><ol><li>Vad betyder ordet biologi?</li><li>Vad menas med att en undersökning är systematisk?</li><li>Välj två av biologerna i bild 1.1. Ge ett exempel på en fråga som var och en kan undersöka.</li></ol></div><h3>Från fråga till plan</h3><p>All forskning börjar med nyfikenhet. Men en bra undersökning börjar med en <strong class='green'>undersökningsbar fråga</strong>: en fråga som går att besvara med mätningar eller observationer. ”Är solrosor fina?” är en åsikt. ”Hur mycket växer en solros på en vecka?” går att mäta.</p><table class=\"tbl\"><tr><th>Går inte att undersöka</th><th>Går att undersöka</th><th>Varför är den bättre?</th></tr><tr><td>Är musik bra när man pluggar?</td><td>Kommer man ihåg fler ord efter att ha lyssnat på musik än efter tystnad?</td><td>Den säger vad som ska mätas (antal ord) och vad som ska jämföras.</td></tr><tr><td>Är krasse bra?</td><td>Växer krasse högre i ljus än i mörker?</td><td>Man kan mäta höjden i millimeter.</td></tr></table><h3>Forskning är en cykel</h3><div class=\"row w\"><div class=\"main\"><p>Arbetet följer ofta stegen i bild 1.2. Efter frågan formulerar forskaren en <strong class='green'>hypotes</strong>: ett möjligt svar på frågan som går att pröva, med en motivering. Därefter planeras och görs en undersökning, och resultatet leder till en slutsats och ofta till en ny fråga. Svaret ska bygga på <strong class='green'>belägg</strong>, alltså mätningar och observationer, och inte på vad någon tycker.</p><p>En <strong class='green'>teori</strong> är något större än en hypotes: en förklaring som har prövats av många forskare under lång tid och som stämmer med väldigt många observationer. Evolutionsteorin och cellteorin är exempel.</p></div><div class=\"side\"><div class=\"fig\"><img src=\"bilder/biologi-omrade1/l_cykel.png\"><div class=\"cap\"><b>Bild 1.2</b> Den vetenskapliga arbetsgången. I verkligheten hoppar forskare ofta fram och tillbaka mellan stegen.</div></div></div></div><h3>Ett rättvist försök</h3><div class=\"row\"><div class=\"main\"><p><span class='fake'>Påhittat exempel</span> Klass 7B undrar om krasse behöver ljus för att växa. Hypotesen är: <em>Krassen i ljus växer högre, eftersom växter behöver ljus för fotosyntesen.</em> En <strong class='green'>variabel</strong> är något som kan ändras eller mätas. För att testet ska bli rättvist får bara <em>en</em> variabel ändras åt gången. Allt annat måste vara lika, annars vet man inte vad som orsakade resultatet.</p><p>Ofta har man också en <strong class='green'>kontrollgrupp</strong>, där man inte ändrar något, så att man har något att jämföra med. I krassförsöket är krassen i ljus kontrollgrupp.</p></div><div class=\"side\"><div class=\"bx begrepp\"><span class=\"rb\">Begrepp</span><b class=\"t\">Undersökningsbar fråga</b><p>En fråga som kan besvaras med mätningar eller observationer.</p><b class=\"t\">Hypotes</b><p>Ett möjligt, prövbart svar med en motivering.</p><b class=\"t\">Variabel</b><p>Något som kan ändras eller mätas i en undersökning.</p><b class=\"t\">Kontrollgrupp</b><p>Grupp där man inte ändrar något, att jämföra med.</p></div></div></div><div class=\"fig\" style=\"width:78%\"><img src=\"bilder/biologi-omrade1/v_krasse.png\"><div class=\"cap\"><b>Bild 1.3</b> Krasse som vuxit i sju dagar i ljus (A) och i en mörk låda (B).</div></div><table class=\"tbl\"><tr><th>Typ av variabel</th><th>Vad betyder det?</th><th>I krassförsöket</th></tr><tr><td>Oberoende variabel</td><td>Det du själv ändrar med flit.</td><td>Ljus eller mörker</td></tr><tr><td>Beroende variabel</td><td>Det du mäter – det som kanske påverkas.</td><td>Krassens höjd i mm</td></tr><tr><td>Kontrollerade variabler</td><td>Allt annat, som måste vara lika i båda försöken.</td><td>Jord, vatten, temperatur, antal frön, tid</td></tr></table><h3>Säkerhet i labbet</h3><div class=\"row w\"><div class=\"main\"><ol class=\"steps\"><li>Läs hela instruktionen innan du börjar.</li><li>Använd skyddsglasögon och förkläde när läraren säger det. Sätt upp långt hår.</li><li>Ät, drick eller smaka aldrig något i labbet.</li><li>Säg till direkt om något går sönder eller om du skadar dig.</li><li>Städa och tvätta händerna när du är klar.</li></ol></div><div class=\"side\"><div class=\"bx varning\"><span class=\"rb\">Faroetiketter</span><p>Kemikalier som kan vara farliga har en varningssymbol på förpackningen. Läs alltid etiketten innan du använder något.</p></div><div class=\"bx tank\"><span class=\"rb\">Tänk efter</span><p>Varför ska man aldrig äta i labbet, även när man bara använder ofarliga saker just den dagen?</p></div></div></div><div class=\"kolla\"><span class=\"kr\">Kolla dig själv 1.1.1</span><ol><li>Gör frågan ”Är hundar snälla?” om till en undersökningsbar fråga.</li><li>Vad är skillnaden mellan oberoende och beroende variabel?</li><li>Varför behövs en kontrollgrupp?</li><li>Varför får man bara ändra en variabel åt gången?</li></ol></div>", "fordjupning": "<p>Föreställ dig att ett företag påstår att deras nya tablett gör att förkylningar går över snabbare. Hur skulle man testa det? Det låter enkelt: ge tabletten till några förkylda personer och se om de blir friska. Men de flesta förkylningar går över av sig själva inom en vecka. Hur vet man då att det var tabletten som hjälpte? En bra plan svarar på det i förväg.</p><div class=\"fig\" style=\"width:82%\"><img src=\"bilder/biologi-omrade1/f_rct.png\"><div class=\"cap\"><b>Bild F1.1</b> En randomiserad, dubbelblind och placebokontrollerad studie: en av de mest pålitliga sorternas medicinska försök.</div></div><h3>Så motiverar du valen i din plan</h3><div class=\"row\"><div class=\"main\"><p><strong>Variabler.</strong> Välj en oberoende variabel och motivera varför just den. Välj en beroende variabel som verkligen mäter det du vill veta (giltighet). Lista vad som måste hållas lika.</p><p><strong>Kontrollgrupp och placebo.</strong> Kontrollgruppen får inte behandlingen. Får den en likadan tablett utan verksamt ämne, kan förväntningar inte förklara skillnaden.</p><p><strong>Randomisering.</strong> Slumpen bestämmer vem som hamnar i vilken grupp. Annars kan forskaren omedvetet lägga de friskaste i den ena gruppen.</p><p><strong>Blindning.</strong> Om varken deltagare eller forskare vet vem som fått vad är studien dubbelblind. Då blir det svårare att påverka resultatet, även omedvetet.</p><p><strong>Antal upprepningar.</strong> Med fem personer i varje grupp kan slumpen avgöra resultatet. Med hundratals blir slumpens betydelse liten. I ett skolförsök kan du inte ha hundratals, så du måste vara öppen med vad det betyder för hur säker slutsatsen blir.</p></div><div class=\"side\"><div class=\"bx begrepp\"><span class=\"rb\">Begrepp</span><b class=\"t\">Randomisering</b><p>Slumpmässig fördelning till grupper.</p><b class=\"t\">Dubbelblind</b><p>Varken deltagare eller forskare vet vem som fått vad.</p><b class=\"t\">Stickprov</b><p>De individer man undersöker, som ska representera en större grupp.</p></div><div class=\"bx tank\"><span class=\"rb\">Resonera om störningar</span><p>Du ska testa om du minns fler ord med musik. Vad kan störa? Hur kan du planera så att varje störning minskar?</p></div></div></div><table class=\"tbl\"><tr><th>Del av planen</th><th>Fråga att svara på</th><th>Motivera</th></tr><tr><td>Frågeställning</td><td>Går den att besvara med mätning?</td><td>Skriv vad som ska mätas.</td></tr><tr><td>Variabler</td><td>Vad ändras, mäts och hålls lika?</td><td>Varför just dessa?</td></tr><tr><td>Mätmetod</td><td>Hur mäter jag, med vilken noggrannhet?</td><td>Varför är metoden giltig?</td></tr><tr><td>Upprepning</td><td>Hur många försök och deltagare?</td><td>Hur påverkar antalet slumpen?</td></tr><tr><td>Störningar</td><td>Vad kan göra resultatet fel?</td><td>Hur förebygger jag det?</td></tr></table>"}, nivaStandard: "vanlig"};
innehall["biologi-m-1-1-2"] = {nivaer: {"lattlast": "<section class=\"sec m3\"><div class=\"lp\"><span class=\"p1\">LÄS</span><span class=\"t\">Delområde 1.1 · Moment 1.1.2</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">1.1.2 Dokumentera</h2><div class=\"t\"><p>När du mäter ska du skriva ner värdena direkt. Använd en <strong>tabell</strong>.</p><p>Tabellen ska ha rubriker. Skriv också enhet, till exempel mm eller s.</p><p><span class='fake'>Påhittade siffror</span> Så här kan Ellas tabell se ut:</p><table class=\"tb\"><tr><th>Dag</th><th>Ljus (mm)</th><th>Mörker (mm)</th></tr><tr><td class=\"n\">1</td><td class=\"n\">5</td><td class=\"n\">5</td></tr><tr><td class=\"n\">3</td><td class=\"n\">15</td><td class=\"n\">25</td></tr><tr><td class=\"n\">5</td><td class=\"n\">28</td><td class=\"n\">42</td></tr><tr><td class=\"n\">7</td><td class=\"n\">40</td><td class=\"n\">60</td></tr></table><div class=\"fig\" style=\"width:55%\"><img src=\"bilder/biologi-omrade1/l_stapel.png\"></div><p>Ett <strong>diagram</strong> gör siffrorna lätta att jämföra. Ella ritar ett stapeldiagram.</p><p>Ett bra diagram har <strong>rubrik</strong>. Axlarna har namn och enhet. Staplarna har namn.</p><h3>Så skriver du en rapport</h3><ol class=\"st\"><li><b>Fråga.</b> Vad ville vi ta reda på?</li><li><b>Så gjorde vi.</b> Vad ändrade vi? Vad mätte vi? Vad höll vi lika?</li><li><b>Resultat.</b> Tabell och diagram.</li><li><b>Slutsats.</b> Svara på frågan. Skriv vad som kan ha blivit fel.</li></ol></div><div class=\"kom\"><span class=\"ex\">!</span><div><span class=\"lb\">KOM IHÅG</span><span class=\"tx\">Skriv värdena i en tabell med rubriker och enheter. Rita ett diagram med rubrik och axlar.</span></div></div></section><section class=\"sec m3\"><div class=\"lp\"><span class=\"p1 ova\">ÖVA</span><span class=\"t\">Delområde 1.1 · Moment 1.1.2</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">Öva: 1.1.2 Dokumentera</h2><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">1</span><div><span class=\"ty\">RINGA IN</span><span class=\"q\">Vad ska stå i tabellens rubrik?</span><div class=\"chips\"><span>Höjd (mm)</span><span>Bara en siffra</span><span>Inget</span></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">2</span><div><span class=\"ty\">RITA OCH SKRIV</span><span class=\"q\">Rita ett stapeldiagram: Grupp A 12 cm, Grupp B 8 cm. Skriv rubrik och namn på axlarna.</span><div class=\"ln\"><i></i><i></i><i></i><i></i><i></i><i></i></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">3</span><div><span class=\"ty\">SKRIV SIFFROR</span><span class=\"q\">Sätt delarna av rapporten i rätt ordning. Skriv 1, 2, 3 och 4.</span><div class=\"nrbox\"><div><i></i>Slutsats</div><div><i></i>Fråga</div><div><i></i>Resultat</div><div><i></i>Så gjorde vi</div></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">4</span><div><span class=\"ty\">FYLL I</span><span class=\"q\">Skriv rätt ord på linjen.</span><span class=\"bank\">Ord att välja: tabell · rubrik · enhet</span><div class=\"fy\"><p>Man skriver värdena i en ______________.</p><p>Ett diagram ska ha en ______________.</p><p>Efter siffran skriver man en ______________, till exempel mm.</p></div></div></div></div></section>", "vanlig": "<p>Under försöket mäter klassen krassen varje dag och skriver direkt ner värdena i en <strong class='green'>tabell</strong>. Tabellen ska ha rubriker, och efter varje mått ska enheten stå, till exempel mm eller s. När försöket är klart räknar man ut <strong class='green'>medelvärdet</strong> för varje grupp: lägg ihop alla värden och dela med antalet värden.</p><div class=\"row w\"><div class=\"main\"><table class=\"tbl num\"><tr><th>Dag</th><th>1</th><th>3</th><th>5</th><th>7</th></tr><tr><td>A · ljus (mm)</td><td>5</td><td>15</td><td>28</td><td>40</td></tr><tr><td>B · mörker (mm)</td><td>5</td><td>25</td><td>42</td><td>60</td></tr></table><p class=\"cap\" style=\"margin-top:-4pt\"><b>Tabell 1.1</b> <span class=\"fake\">Påhittade värden</span> Krassens medelhöjd i klassens försök.</p><h3>Välj diagram</h3><p>Ett diagram gör det lättare att se mönster. Ett <strong>stapeldiagram</strong> passar när du jämför grupper, till exempel höjden efter sju dagar. Ett <strong>linjediagram</strong> passar när något förändras över tid. Tiden sätts på x-axeln och det du mäter på y-axeln. Glöm inte rubrik, namn och enheter på axlarna.</p><p>Läs av diagrammet noga: vilken stapel är högst, hur stor är skillnaden, och vad står siffrorna för?</p></div><div class=\"side\"><div class=\"fig\"><img src=\"bilder/biologi-omrade1/l_stapel.png\"><div class=\"cap\"><b>Bild 1.4</b> Krassens höjd efter 7 dagar.</div></div></div></div><h3>Skriva en rapport</h3><p>När du har gjort en undersökning redovisar du den i en rapport. Den ska vara så tydlig att någon annan kan göra om försöket och kontrollera ditt resultat.</p><div class=\"cards\" style=\"grid-template-columns:repeat(5,1fr)\"><div class=\"card\"><b class=\"h\">Syfte och frågeställning</b>Vad vill du ta reda på?</div><div class=\"card\"><b class=\"h\">Hypotes</b>Vad tror du och varför?</div><div class=\"card\"><b class=\"h\">Material och metod</b>Vad använde du och hur gjorde du?</div><div class=\"card\"><b class=\"h\">Resultat</b>Vad hände? Tabeller och diagram.</div><div class=\"card\"><b class=\"h\">Diskussion och slutsats</b>Vad betyder resultatet? Felkällor?</div></div><div class=\"row one\"><div class=\"main\"><div class=\"bx klimat\"><span class=\"rb\">Digitala verktyg</span><p>Ett kalkylprogram räknar ut medelvärden och ritar diagram åt dig. Mobilkameran kan dokumentera försöket med bilder. Du måste ändå själv avgöra om diagrammet visar det du vill veta.</p></div></div></div><div class=\"kolla\"><span class=\"kr\">Kolla dig själv 1.1.2</span><ol><li>Vad ska en tabell innehålla?</li><li>När passar ett stapeldiagram och när ett linjediagram?</li><li>Räkna ut medelvärdet av 12, 14 och 13 mm.</li><li>Vilka delar ingår i en rapport?</li></ol></div>", "fordjupning": "<p>Ett diagram visar inte bara svaret. Det visar också hur osäkert svaret är. <span class='fake'>Påhittat exempel</span> En grupp undersökte hur temperaturen påverkar gasbildningen hos jäst. De gjorde tre försök vid varje temperatur och mätte hur mycket en ballong växte.</p><table class=\"tbl num\"><tr><th>Temperatur</th><th>Försök 1</th><th>Försök 2</th><th>Försök 3</th><th>Medelvärde</th></tr><tr><td>10 °C</td><td>13 cm</td><td>12 cm</td><td>14 cm</td><td>13 cm</td></tr><tr><td>25 °C</td><td>22 cm</td><td>24 cm</td><td>23 cm</td><td>23 cm</td></tr><tr><td>40 °C</td><td>31 cm</td><td>18 cm</td><td>30 cm</td><td>?</td></tr></table><h3>Det avvikande värdet</h3><div class=\"row w\"><div class=\"main\"><p>Vid 40 °C avviker ett värde mycket från de andra (18 cm). Om man räknar med det blir medelvärdet 26 cm. Utan det blir det 30,5 cm. Vad ska man göra? Man ska inte stryka ett värde bara för att det passar illa. Man frågar först: Finns det en rimlig förklaring, till exempel att ballongen satt löst? Om ja, redovisa värdet, förklara varför det kan vara fel och visa resultatet med och utan det. Om nej, gör fler försök.</p><h3>Osäkerhet</h3><p>Ju mer mätvärdena skiljer sig inom en grupp, desto osäkrare är medelvärdet. Man kan redovisa osäkerheten genom att visa lägsta och högsta värde. Skillnaden mellan 10 och 25 °C är stor jämfört med spridningen. Skillnaden mellan 25 och 40 °C är mindre tydlig, eftersom ett av värdena avviker.</p></div><div class=\"side\"><div class=\"bx begrepp\"><span class=\"rb\">Begrepp</span><b class=\"t\">Avvikande värde</b><p>Ett värde som ligger långt från de andra.</p><b class=\"t\">Spridning</b><p>Hur mycket mätvärdena skiljer sig åt.</p><b class=\"t\">Osäkerhet</b><p>Hur säkert ett resultat är.</p></div><div class=\"bx klimat\"><span class=\"rb\">Digitala verktyg</span><p>I ett kalkylblad kan du räkna medelvärde med och utan ett värde, och rita diagram med både medelvärden och enskilda mätpunkter.</p></div></div></div><div class=\"row one\"><div class=\"main\"><div class=\"bx fundera\"><span class=\"rb\">Fundera</span><p>Vilken slutsats kan du dra om temperaturens påverkan, och vilken kan du inte dra? Vad skulle du göra för att bli säkrare?</p></div></div></div>"}, nivaStandard: "vanlig"};
innehall["biologi-m-1-1-3"] = {nivaer: {"lattlast": "<section class=\"sec m4\"><div class=\"lp\"><span class=\"p1\">LÄS</span><span class=\"t\">Delområde 1.1 · Moment 1.1.3</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">1.1.3 Värdera</h2><div class=\"t\"><p>Ett resultat kan bli fel. Det beror på <strong>felkällor</strong>.</p><table class=\"tb\"><tr><th>Felkälla</th><th>Exempel</th></tr><tr><td>Slump</td><td>Man läser av linjalen lite olika varje gång.</td></tr><tr><td>Misstag</td><td>Man mäter från fel ställe på linjalen.</td></tr><tr><td>Olika villkor</td><td>Den ena krassen får mer vatten.</td></tr></table><p><strong>Slump</strong> är sådant som bara händer. Därför gör man om testet flera gånger. Då blir resultatet säkrare.</p><div class=\"fig\" style=\"width:55%\"><img src=\"bilder/biologi-omrade1/l_stapel.png\"></div><p>Slutsatsen ska stämma med resultatet.</p><p><strong>Ellas slutsats:</strong> Krassen blir högre i mörker. Den växer på höjden för att leta efter ljus. Men den mår bäst i ljus.</p><p>Hypotesen var alltså fel. Det gör inget! Man lär sig ändå.</p><p>Ella testade bara krasse. Hon kan inte säga att alla växter gör så. Skriv alltid vad du inte vet.</p></div><div class=\"kom\"><span class=\"ex\">!</span><div><span class=\"lb\">KOM IHÅG</span><span class=\"tx\">Resultatet kan bli fel. Gör om testet flera gånger. Slutsatsen ska stämma med resultatet.</span></div></div></section><section class=\"sec m4\"><div class=\"lp\"><span class=\"p1 ova\">ÖVA</span><span class=\"t\">Delområde 1.1 · Moment 1.1.3</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">Öva: 1.1.3 Värdera</h2><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">1</span><div><span class=\"ty\">RINGA IN</span><span class=\"q\">En fläkt blåser på en av krassarna. Vad är det?</span><div class=\"chips\"><span>En felkälla</span><span>En slutsats</span><span>En hypotes</span></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">2</span><div><span class=\"ty\">SANT ELLER FALSKT</span><span class=\"q\">Kryssa i rätt ruta.</span><div class=\"sf\"><table><tr><th></th><th>Sant</th><th>Falskt</th></tr><tr><td>Man kan få fel resultat av slump.</td><td class=\"c\"><b class=\"bx\"></b></td><td class=\"c\"><b class=\"bx\"></b></td></tr><tr><td>Det är dåligt om hypotesen var fel.</td><td class=\"c\"><b class=\"bx\"></b></td><td class=\"c\"><b class=\"bx\"></b></td></tr><tr><td>Det är bra att göra testet flera gånger.</td><td class=\"c\"><b class=\"bx\"></b></td><td class=\"c\"><b class=\"bx\"></b></td></tr></table></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">3</span><div><span class=\"ty\">FYLL I</span><span class=\"q\">Skriv rätt ord på linjen.</span><span class=\"bank\">Ord att välja: slutsatsen · felkälla · flera</span><div class=\"fy\"><p>Något som kan ge fel resultat kallas en ______________.</p><p>Man gör testet ______________ gånger.</p><p>______________ ska stämma med resultatet.</p></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">4</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Varför är det bra att göra ett test flera gånger?</span><div class=\"ln\">Det är bra eftersom<i></i><i></i></div></div></div></div></section>", "vanlig": "<p>En forskare frågar sig alltid: Kan jag lita på resultatet? Mätte vi rätt sak? Ett resultat kan bli fel på flera sätt. Sådant som kan ha påverkat resultatet utan att vi ville det kallas <strong class='green'>felkällor</strong>.</p><table class=\"tbl\"><tr><th>Typ av felkälla</th><th>Exempel i krassförsöket</th><th>Vad hjälper?</th></tr><tr><td>Slump</td><td>En krasse får av en slump dålig jord. Någon läser av linjalen lite olika varje gång.</td><td>Fler mätningar och upprepning. Slumpen jämnar då ut sig.</td></tr><tr><td>Systematiskt fel</td><td>Mörka lådan blir varmare, så temperaturen och inte ljuset påverkar. Eller man mäter alltid från fel ställe.</td><td>Bättre planering: håll alla andra variabler lika. Kontrollera mätmetoden.</td></tr></table><p>Man gör därför försöket flera gånger och räknar ut ett medelvärde. Då får slumpen mindre betydelse. Ett enda avvikande värde bör man undersöka: var det ett misstag, eller säger det något?</p><div class=\"row w\"><div class=\"main\"><h3 style='margin-top:0'>Tillförlitlighet och giltighet</h3><p><strong class='green'>Tillförlitlighet</strong> handlar om hur säkra mätningarna är: skulle vi få samma resultat om vi gjorde om försöket? <strong class='green'>Giltighet</strong> handlar om huruvida vi har mätt det vi ville veta. Är höjden ett bra mått på om krassen ”växer bra”? Det hade kanske varit bättre att väga krassen eller titta på färgen.</p><h3>Slutsatsen</h3><p>Slutsatsen ska svara på frågan och stämma med resultatet. Klassens slutsats: <em>Krasse som växer i mörker blir högre men svagare än krasse i ljus. Höjden är inte ett bra mått på hur bra en växt mår.</em> Skriv också vad du inte kan veta. Klassen testade bara krasse, så den kan inte säga att alla växter gör så.</p></div><div class=\"side\"><div class=\"bx begrepp\"><span class=\"rb\">Begrepp</span><b class=\"t\">Felkälla</b><p>Något som kan ha påverkat resultatet utan att man ville det.</p><b class=\"t\">Slump</b><p>Tillfälliga variationer som inte beror på det man undersöker.</p><b class=\"t\">Tillförlitlighet</b><p>Hur säkra och upprepbara mätningarna är.</p><b class=\"t\">Giltighet</b><p>Om man har mätt det man ville undersöka.</p><b class=\"t\">Slutsats</b><p>Det man kan dra för svar på frågan utifrån resultatet.</p></div><div class=\"bx visste\"><span class=\"rb\">Bra att veta</span><p>Ett resultat som inte stämmer med hypotesen är inte ett misslyckande. Hypotesen var att krassen blir högre i ljus. Resultatet visade något annat och klassen lärde sig något nytt. Så går forskningen framåt.</p></div></div></div><div class=\"kolla\"><span class=\"kr\">Kolla dig själv 1.1.3</span><ol><li>Vad är skillnaden mellan slump och systematiskt fel? Ge ett exempel på vardera.</li><li>Varför minskar slumpens betydelse när man upprepar ett försök?</li><li>Vad menas med giltighet?</li><li>Varför ska en slutsats också säga vad man inte vet?</li></ol></div>", "fordjupning": "<p>Många nyheter bygger på undersökningar där forskare har jämfört grupper av människor, till exempel ”personer som äter mycket fisk lever längre”. Sådana <strong class='green'>observationsstudier</strong> är viktiga, men grupperna kan skilja sig åt på många andra sätt än det man undersöker.</p><h3>Störfaktorer</h3><div class=\"row w\"><div class=\"main\"><p>En <strong class='green'>störfaktor</strong> är något som påverkar både det man tror är orsaken och det man mäter. Kanske äter personer som äter mycket fisk också mer grönsaker, röker mindre och har högre inkomst. Då kan det vara de sakerna, och inte fisken, som gör att de lever längre.</p><p>Forskare försöker räkna bort kända störfaktorer, men det kan alltid finnas sådana som ingen har tänkt på. Därför är kontrollerade experiment med slumpad fördelning det säkraste sättet att visa orsak.</p></div><div class=\"side\"><div class=\"fig\"><img src=\"bilder/biologi-omrade1/f_storfaktor.png\"><div class=\"cap\"><b>Bild F1.2</b> En störfaktor kan skapa ett samband mellan två saker som inte påverkar varandra.</div></div></div></div><h3>Slumpen lurar</h3><div class=\"row\"><div class=\"main\"><p>Om du singlar slant tio gånger är det inte konstigt att få sju krona. Det betyder inte att myntet är fusk. Samma sak gäller i biologiska undersökningar: små skillnader mellan små grupper kan bero på ren slump. Ju större stickprov och ju större skillnad, desto säkrare kan man vara på att skillnaden är verklig.</p><p>När du värderar ett försök, resonera om vilka felkällor som är störst, hur mycket de kan ha påverkat slutsatsen och hur du skulle förbättra försöket. Sluta med att säga hur säker slutsatsen är: ”Resultatet tyder på …, men eftersom … kan vi inte vara säkra på …”.</p></div><div class=\"side\"><div class=\"bx begrepp\"><span class=\"rb\">Begrepp</span><b class=\"t\">Observationsstudie</b><p>Man jämför grupper utan att själv ändra något.</p><b class=\"t\">Störfaktor</b><p>En faktor som påverkar både den misstänkta orsaken och resultatet.</p></div><div class=\"bx tank\"><span class=\"rb\">Tänk efter</span><p>”Barn som har många böcker hemma får bättre betyg.” Ge två möjliga störfaktorer.</p></div></div></div>"}, nivaStandard: "vanlig"};
innehall["biologi-m-1-1-l"] = {nivaer: {"lattlast": "<section class=\"sec m5\"><div class=\"lp\"><span class=\"p1\">LABB</span><span class=\"t\">Delområde 1.1 · Labb (45 min)</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">Labb 1.1 Reaktionstid</h2><div class=\"t\"><p><strong>Fråga:</strong> Hur snabb är din reaktion? Vi mäter med en fallande linjal.</p><p>Ni är två och två. Ni behöver en linjal på 30 cm och en penna.</p><p>Ni gör på samma sätt varje gång: samma linjal, samma hand och fem försök. Då blir testet rättvist.</p><div class=\"fig\" style=\"width:48%\"><img src=\"bilder/biologi-omrade1/v_linjal.png\"></div><ol class='st'><li>Din kompis håller linjalen lodrätt. Noll ska vara vid din tumme och pekfinger.</li><li>Kompisen släpper linjalen utan att säga till.</li><li>Du fångar den så fort du kan.</li><li>Läs av var du fångade linjalen. Skriv ner centimeter.</li><li>Gör fem försök. Byt sedan plats.</li></ol><h3>Räkna om till tid</h3><table class=\"tb\"><tr><th>Fallsträcka (cm)</th><th>Reaktionstid (s)</th></tr><tr><td class=\"n\">5</td><td class=\"n\">0,10</td></tr><tr><td class=\"n\">10</td><td class=\"n\">0,14</td></tr><tr><td class=\"n\">15</td><td class=\"n\">0,17</td></tr><tr><td class=\"n\">20</td><td class=\"n\">0,20</td></tr><tr><td class=\"n\">25</td><td class=\"n\">0,23</td></tr><tr><td class=\"n\">30</td><td class=\"n\">0,25</td></tr></table><p><strong>Säkerhet:</strong> Sitt eller stå stadigt. Skriv bara ner ditt eget värde. Du behöver inte visa det för alla.</p></div><div class=\"kom\"><span class=\"ex\">!</span><div><span class=\"lb\">KOM IHÅG</span><span class=\"tx\">Fallsträckan visar din reaktionstid. Gör flera försök och skriv i en tabell.</span></div></div></section><section class=\"sec m5\"><div class=\"lp\"><span class=\"p1 ova\">ÖVA</span><span class=\"t\">Delområde 1.1 · Labb (45 min)</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">Öva: Labb 1.1 Reaktionstid</h2><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">1</span><div><span class=\"ty\">FYLL I</span><span class=\"q\">Skriv rätt ord på linjen.</span><span class=\"bank\">Ord att välja: cm · fem · tabell</span><div class=\"fy\"><p>Jag gör ______________ försök.</p><p>Jag skriver värdena i en ______________.</p><p>Jag mäter fallsträckan i ______________.</p></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">2</span><div><span class=\"ty\">RITA OCH SKRIV</span><span class=\"q\">Rita ett stapeldiagram över dina fem försök. Skriv rubrik och namn på axlarna.</span><div class=\"ln\"><i></i><i></i><i></i><i></i><i></i><i></i></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">3</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Vad blev din slutsats? Svara på frågan: Hur snabb är din reaktion?</span><div class=\"ln\">Min reaktionstid var ungefär<i></i><i></i></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">4</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Nämn en felkälla. Vad kunde ha blivit fel?</span><div class=\"ln\">En felkälla är<i></i><i></i></div></div></div></div></section>", "vanlig": "<p>Du ska planera och genomföra en hel undersökning på 45 minuter. Hur snabbt reagerar du? Med en linjal som någon släpper kan du mäta det: ju kortare linjalen hinner falla innan du fångar den, desto snabbare är din reaktion.</p><div class=\"fig\" style=\"width:52%\"><img src=\"bilder/biologi-omrade1/v_linjal.png\"><div class=\"cap\"><b>Bild 1.5</b> Linjalen släpps utan förvarning. Du fångar den med tumme och pekfinger. Läs av vid fingrarna.</div></div><div class=\"row w\"><div class=\"main\"><p><strong class='green'>Frågeställning:</strong> Reagerar jag snabbare med en hand än med den andra? (Eller välj en egen fråga.)</p><p><strong class='green'>Hypotes:</strong> Skriv vad du tror och motivera.</p><p><strong class='green'>Material:</strong> linjal 30 cm, penna, papper.</p><h3>Gör så här</h3><ol class=\"steps\"><li>Bestäm oberoende variabel (vilken hand), beroende variabel (fallsträckan i cm) och vad som ska hållas lika.</li><li>Din kompis håller linjalen lodrätt med noll vid dina fingrar. Släpp utan förvarning.</li><li>Läs av var du fångade linjalen. Gör minst fem försök med varje hand.</li><li>Skriv i en tabell, räkna medelvärde och omvandla till tid med tabellen intill.</li><li>Rita ett stapeldiagram. Skriv slutsats och felkällor.</li></ol></div><div class=\"side\"><table class=\"tbl num\"><tr><th>Fallsträcka</th><th>Reaktionstid</th></tr><tr><td>5 cm</td><td>0,10 s</td></tr><tr><td>10 cm</td><td>0,14 s</td></tr><tr><td>15 cm</td><td>0,17 s</td></tr><tr><td>20 cm</td><td>0,20 s</td></tr><tr><td>25 cm</td><td>0,23 s</td></tr><tr><td>30 cm</td><td>0,25 s</td></tr></table><div class=\"bx begrepp\"><span class=\"rb\">Variabler</span><b class='t'>Oberoende</b><p>Vilken hand.</p><b class='t'>Beroende</b><p>Fallsträckan.</p><b class='t'>Lika</b><p>Linjal, startläge, förvarning, antal försök.</p></div><div class=\"bx tank\"><span class=\"rb\">Utvärdera</span><p>Kan resultatet bero på övning och inte på handen? Hur kan du förbättra försöket?</p></div></div></div><p class=\"note\">Säkerhet: låg risk. Sitt eller stå stadigt. Redovisa klassens värden, inte personliga.</p>"}, nivaStandard: "vanlig"};
innehall["biologi-m-1-2-1"] = {nivaer: {"lattlast": "<section class=\"sec m6\"><div class=\"lp\"><span class=\"p1\">LÄS</span><span class=\"t\">Delområde 1.2 · Moment 1.2.1</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">1.2.1 Vad kan vetenskap pröva?</h2><div class=\"t\"><p>Ett <strong>påstående</strong> är något man säger är sant.</p><p>Vetenskap kan pröva ett påstående om det går att mäta eller titta. Det man mäter eller ser kallas <strong>belägg</strong>.</p><p>En <strong>åsikt</strong> är vad någon tycker. Åsikter går inte att mäta. Därför kan vetenskapen inte pröva dem.</p><table class=\"tb\"><tr><th>Påstående</th><th>Går det att pröva?</th></tr><tr><td>Vatten fryser vid 0 °C.</td><td>Ja. Man kan mäta temperaturen.</td></tr><tr><td>Hundar har bättre luktsinne än människor.</td><td>Ja. Man kan testa det.</td></tr><tr><td>Katter är gulligare än hundar.</td><td>Nej. Det är en åsikt.</td></tr><tr><td>Ditt stjärntecken bestämmer hur du är.</td><td>Ja. Det är prövat. Det finns inga belägg.</td></tr></table><h3>Pseudovetenskap</h3><p>Ibland låter något som vetenskap, men det finns inga belägg. Det kallas <strong>pseudovetenskap</strong>.</p><p>Horoskopet säger att ditt stjärntecken styr hur du är. Forskare har testat det. De har inte hittat belägg.</p></div><div class=\"kom\"><span class=\"ex\">!</span><div><span class=\"lb\">KOM IHÅG</span><span class=\"tx\">Vetenskap prövar påståenden med belägg. Åsikter går inte att pröva.</span></div></div></section><section class=\"sec m6\"><div class=\"lp\"><span class=\"p1 ova\">ÖVA</span><span class=\"t\">Delområde 1.2 · Moment 1.2.1</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">Öva: 1.2.1 Vad kan vetenskap pröva?</h2><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">1</span><div><span class=\"ty\">KRYSSA</span><span class=\"q\">Vilka påståenden går att pröva? Kryssa i rätt rutor.</span><div class=\"dr\"><div><b class='bx2'></b> Kaniner springer fortare än sköldpaddor.</div><div><b class='bx2'></b> Rött är den finaste färgen.</div><div><b class='bx2'></b> Vatten kokar vid 100 °C.</div><div><b class='bx2'></b> Pizza är godast.</div></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">2</span><div><span class=\"ty\">RINGA IN</span><span class=\"q\">Vad är belägg?</span><div class=\"chips\"><span>Mätningar och observationer</span><span>Vad någon tycker</span><span>En gissning utan test</span></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">3</span><div><span class=\"ty\">FYLL I</span><span class=\"q\">Skriv rätt ord på linjen.</span><span class=\"bank\">Ord att välja: belägg · åsikt · pseudovetenskap</span><div class=\"fy\"><p>Mätningar som visar något kallas ______________.</p><p>Det man tycker kallas en ______________.</p><p>Det som låter som vetenskap men saknar belägg kallas ______________.</p></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">4</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Hur kan man pröva påståendet: Hundar har bättre luktsinne än människor?</span><div class=\"ln\">Man kan<i></i><i></i></div></div></div></div></section>", "vanlig": "<p>Ett <strong class='green'>påstående</strong> är något man säger är sant. Naturvetenskapen kan pröva ett påstående om det går att undersöka med mätningar eller observationer. Det man mäter eller ser kallas <strong class='green'>belägg</strong>. Vi skiljer mellan tre saker:</p><div class=\"cards\" style=\"grid-template-columns:repeat(3,1fr)\"><div class=\"card\"><b class=\"h\">Belägg</b>Mätningar och observationer som andra kan kontrollera. Exempel: vatten fryser vid 0 °C.</div><div class=\"card\"><b class=\"h\">Åsikt</b>Vad någon tycker. Går inte att mäta. Exempel: pizza är godast.</div><div class=\"card\"><b class=\"h\">Tro</b>Något man är övertygad om utan att det kan prövas. Vetenskapen kan varken bevisa eller motbevisa det.</div></div><table class=\"tbl\"><tr><th>Påstående</th><th>Går det att pröva?</th><th>Hur?</th></tr><tr><td>Hundar har bättre luktsinne än människor.</td><td>Ja</td><td>Man kan testa hur svaga lukter olika djur hittar.</td></tr><tr><td>Katter är gulligare än hundar.</td><td>Nej</td><td>Det är en åsikt. Det finns inget att mäta.</td></tr><tr><td>Krasse gror snabbare vid 20 °C än vid 10 °C.</td><td>Ja</td><td>Mät hur många frön som gror vid olika temperaturer.</td></tr><tr><td>Det är fel att jaga varg.</td><td>Nej, inte bara med mätningar</td><td>Det är en värdering. Biologi kan ge fakta till diskussionen, men inte avgöra vad som är rätt.</td></tr></table><h3>Ett påstående måste kunna visas vara fel</h3><div class=\"row w\"><div class=\"main\"><p>Ett påstående som går att pröva måste också kunna visa sig vara fel. Om ett påstående passar med allt som kan hända kan man aldrig pröva det. ”Det kommer att hända något bra eller dåligt för dig i morgon” går aldrig att motbevisa, men säger inte heller något.</p><h3>Pseudovetenskap</h3><p>Ibland låter något vetenskapligt fast det inte är det. Det kallas <strong class='green'>pseudovetenskap</strong>: ”pseudo” betyder falsk. Det använder gärna ord som ”forskare” eller ”kliniskt bevisat”, men påståendena har inte prövats ordentligt, eller har prövats och visat sig vara fel.</p><p>Horoskop är ett exempel. År 1985 fick 28 erfarna astrologer i ett dubbelblint test para ihop födelsehoroskop med personlighetsprofiler. De lyckades inte bättre än slumpen (Carlson, <em>Nature</em>).</p></div><div class=\"side\"><div class=\"bx begrepp\"><span class=\"rb\">Begrepp</span><b class=\"t\">Påstående</b><p>Något man säger är sant.</p><b class=\"t\">Belägg</b><p>Mätningar och observationer som visar något.</p><b class=\"t\">Åsikt</b><p>Vad någon tycker. Går inte att pröva med mätningar.</p><b class=\"t\">Pseudovetenskap</b><p>Låter som vetenskap men saknar prövade belägg.</p></div><div class=\"bx fundera\"><span class=\"rb\">Fundera</span><p>Varför är det en styrka för vetenskapen att den kan visa sig ha fel?</p></div></div></div><table class=\"tbl num\"><tr><th>Vetenskap</th><th>Pseudovetenskap</th></tr><tr><td>Påståenden går att pröva och kan visa sig vara fel.</td><td>Påståenden är vaga eller går inte att pröva.</td></tr><tr><td>Bygger på undersökningar med många deltagare.</td><td>Bygger på enstaka berättelser: ”Det funkade för mig!”</td></tr><tr><td>Granskas av andra experter.</td><td>Granskas inte, eller bara av den som säljer något.</td></tr><tr><td>Ändrar sig när nya belägg kommer.</td><td>Håller fast vid idén, vad undersökningarna än visar.</td></tr></table><div class=\"kolla\"><span class=\"kr\">Kolla dig själv 1.2.1</span><ol><li>Vad är skillnaden mellan belägg och åsikt?</li><li>Varför kan man inte pröva ”Det är fel att jaga varg” med bara mätningar?</li><li>Ge två kännetecken på pseudovetenskap.</li></ol></div>", "fordjupning": "<p>Naturvetenskapen är kraftfull, men den svarar bara på vissa sorters frågor: frågor som går att pröva med belägg. Frågan ”Hur påverkar en gödning tomatplantors skörd?” är en sådan. ”Är det rätt att äta kött?” är en annan sorts fråga. Biologin kan ge fakta om hur djur påverkas och hur klimatet påverkas, men vad som är rätt beror också på värderingar. Därför behövs både fakta och etiska argument.</p><h3>Ett påstående måste kunna visas vara fel</h3><div class=\"row w\"><div class=\"main\"><p>Ett vetenskapligt påstående måste kunna visa sig vara fel. Om alla tänkbara resultat passar med påståendet kan man aldrig pröva det. ”Hälsokosten hjälper om du tror på den, och om den inte hjälper tror du inte tillräckligt” går aldrig att motbevisa. Då har påståendet lämnat vetenskapen.</p><p>Det betyder inte att alla icke-vetenskapliga svar är värdelösa. Konst, etik, religion och filosofi svarar på andra frågor än naturvetenskapen. Problemet uppstår när något gör anspråk på att vara vetenskap utan att kunna prövas.</p></div><div class=\"side\"><div class=\"bx fundera\"><span class=\"rb\">Resonera</span><p>Vilka frågor om samma sak, till exempel jakt på varg, kan naturvetenskapen svara på, och vilka kan den inte avgöra?</p></div></div></div><table class=\"tbl\"><tr><th>Påstående</th><th>Går det att pröva?</th><th>Hur skulle du pröva det?</th></tr><tr><td>Vi sover bättre i ett kallt rum.</td><td>Ja</td><td>Mät sömnlängd eller antal uppvaknanden vid olika temperaturer.</td></tr><tr><td>Naturen mår bäst när människan inte rör den.</td><td>Delvis</td><td>Måste först definiera ”mår bäst” (t.ex. antal arter) och därefter mäta. Värderingen ligger i orden.</td></tr><tr><td>Stjärntecknet styr din personlighet.</td><td>Ja, och prövat</td><td>Dubbelblint test (Carlson, Nature 1985): astrologerna klarade inte mer än slumpen.</td></tr></table>"}, nivaStandard: "vanlig"};
innehall["biologi-m-1-2-2"] = {nivaer: {"lattlast": "<section class=\"sec m7\"><div class=\"lp\"><span class=\"p1\">LÄS</span><span class=\"t\">Delområde 1.2 · Moment 1.2.2</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">1.2.2 När forskare ändrat sig</h2><div class=\"t\"><p>Forskare förklarar hur saker fungerar. En förklaring kallas en <strong>modell</strong>.</p><p>Om nya undersökningar visar något annat, ändrar forskarna modellen. Här är tre exempel.</p><div class=\"sub\"><h3>Pasteur och kolven (1861)</h3><p>Förr trodde många att <strong>mikroorganismer</strong>, alltså mycket små organismer, kunde uppstå av sig själva i mat.</p><p>Pasteur kokade buljong i en kolv med lång böjd hals. Damm fastnade i böjen. Buljongen förblev klar.</p><p>Slutsats: små organismer kommer utifrån. De uppstår inte av sig själva.</p><div class=\"fig\" style=\"width:50%\"><img src=\"bilder/biologi-omrade1/v_pasteur.png\"></div></div><div class=\"sub\"><h3>Semmelweis och händerna (1847)</h3><p>I Wien dog många mammor efter förlossningen i barnsängsfeber. Det dog fler på läkarklinikens avdelning än på barnmorskornas.</p><p>Läkarna hade rört vid döda kroppar. Semmelweis trodde att något följde med händerna. Från 1847 skulle alla tvätta händerna i klorkalklösning.</p><p>Dödligheten sjönk från 11,4 % till 1,3 %. Men många läkare trodde inte på honom.</p><div class=\"fig\" style=\"width:50%\"><img src=\"bilder/biologi-omrade1/f_semmelweis2.png\"></div></div><div class=\"sub\"><h3>Marshall, Warren och magsåren (1982)</h3><p>Förr trodde man att magsår kom av stress och livsstil.</p><p>Marshall och Warren hittade en bakterie i magsäcken, <em>Helicobacter pylori</em>. Många trodde inte på dem.</p><p>År 1984 drack Marshall själv bakterier och fick en inflammation i magsäcken. Gör aldrig så själv! Idag botas magsår med antibiotika och medicin som minskar syran. De fick Nobelpriset 2005.</p><div class=\"fig\" style=\"width:50%\"><img src=\"bilder/biologi-omrade1/f_hpylori.png\"></div></div></div><div class=\"kom\"><span class=\"ex\">!</span><div><span class=\"lb\">KOM IHÅG</span><span class=\"tx\">En modell kan ändras när nya undersökningar visar något annat.</span></div></div></section><section class=\"sec m7\"><div class=\"lp\"><span class=\"p1 ova\">ÖVA</span><span class=\"t\">Delområde 1.2 · Moment 1.2.2</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">Öva: 1.2.2 När forskare ändrat sig</h2><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">1</span><div><span class=\"ty\">DRA STRECK</span><span class=\"q\">Vem upptäckte vad? Dra streck.</span><div class=\"dr\"><div>Pasteur</div><div>handtvätt minskar dödsfall</div><div>Semmelweis</div><div>magsår kommer av en bakterie</div><div>Marshall och Warren</div><div>små organismer kommer utifrån</div></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">2</span><div><span class=\"ty\">RINGA IN</span><span class=\"q\">Vad hände med dödligheten efter handtvätten?</span><div class=\"chips\"><span>Den sjönk</span><span>Den steg</span><span>Den blev lika</span></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">3</span><div><span class=\"ty\">FYLL I</span><span class=\"q\">Skriv rätt ord på linjen.</span><span class=\"bank\">Ord att välja: modell · belägg · bakterie</span><div class=\"fy\"><p>En förklaring kallas en ______________.</p><p>Marshall och Warren hittade en ______________ i magsäcken.</p><p>Forskare ändrar sig när de får nya ______________.</p></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">4</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Varför ändrade forskarna sig i de tre exemplen?</span><div class=\"ln\">De ändrade sig eftersom<i></i><i></i></div></div></div></div></section>", "vanlig": "<p>En <strong class='green'>förklaringsmodell</strong> är ett sätt att förklara hur något fungerar. En modell är en förenkling av verkligheten. Den är användbar så länge den hjälper oss att förstå och förutsäga, men den kan behöva ändras när nya undersökningar visar något annat. Här är tre exempel.</p><h3>Pasteur och svanhalskolven (1861)</h3><div class=\"row w\"><div class=\"main\"><p>Förr trodde många att <strong class='green'>mikroorganismer</strong> kunde uppstå av sig själva i mat som stod framme. Louis Pasteur kokade buljong i två sorters glaskolvar. Kolv A hade ett rakt rör, så att damm och mikroorganismer från luften kunde falla ner. Där blev buljongen grumlig. Kolv B hade en lång, böjd ”svanhals”. Luft kom in, men dammet fastnade i böjen och buljongen förblev klar.</p><p>Pasteur visade att mikroorganismerna kom utifrån och inte uppstod av sig själva. Hans försök var ett bra belägg eftersom bara en sak skilde kolvarna åt: halsens form.</p></div><div class=\"side\"><div class=\"fig\"><img src=\"bilder/biologi-omrade1/v_pasteur.png\"><div class=\"cap\"><b>Bild 1.6</b> Pasteurs svanhalskolvar.</div></div></div></div><h3>Semmelweis och de otvättade händerna (1847)</h3><div class=\"row w\"><div class=\"main\"><p>På Allmänna sjukhuset i Wien fanns på 1840-talet två förlossningsavdelningar. På den ena arbetade läkare och läkarstudenter, som också obducerade döda kroppar. På den andra arbetade barnmorskor, som inte gjorde det. På läkarnas avdelning dog fler mödrar i barnsängsfeber. År 1846 var dödligheten där drygt fyra gånger högre (11,4 % mot 2,8 %).</p><p>År 1847 dog Semmelweis vän Jakob Kolletschka efter att ha skurit sig med en obduktionskniv. Han fick samma symtom som de sjuka mödrarna. Semmelweis drog slutsatsen att ”likpartiklar” fördes över med läkarnas händer. Han krävde att alla skulle tvätta händerna i klorkalklösning. Dödligheten på läkarkliniken sjönk från 11,4 % år 1846 till 1,3 % år 1848.</p><p>Ändå godtogs inte hans idé. Han kunde inte förklara <em>varför</em> det hjälpte, eftersom man ännu inte visste att bakterier kan orsaka sjukdomar, och han publicerade sig sent. Först årtionden senare fick bakterieläran fäste genom Pasteur, Lister och Koch.</p></div><div class=\"side\"><div class=\"fig\"><img src=\"bilder/biologi-omrade1/f_semmelweis2.png\"><div class=\"cap\"><b>Bild 1.7</b> Dödlighet på läkarkliniken före och efter handtvätt.</div></div></div></div><h3>Marshall, Warren och magsåren (1982)</h3><div class=\"row w\"><div class=\"main\"><p>Under större delen av 1900-talet trodde man att magsår kom av stress och livsstil. Man behandlade med syrahämmande medicin, men såren kom ofta tillbaka. Man ansåg dessutom att bakterier inte kunde leva i magsäckens syra.</p><p>År 1982 upptäckte de australiska forskarna Barry Marshall och Robin Warren bakterien <em>Helicobacter pylori</em> i magsäcken. De föreslog att den orsakade sårbildningen. Många trodde inte på dem. År 1984 drack Marshall själv en bakterieodling och fick en inflammation i magsäcken (gastrit). Senare visades att magsår botas när bakterien utrotas med antibiotika och syrahämmande medel. År 2005 fick de Nobelpriset i fysiologi eller medicin.</p><p class='note'>Marshalls självförsök var riskabelt. Forskning på människor måste idag etikprövas.</p></div><div class=\"side\"><div class=\"fig\"><img src=\"bilder/biologi-omrade1/f_hpylori.png\"><div class=\"cap\"><b>Bild 1.8</b> <em>Helicobacter pylori</em> i magsäcken.</div></div></div></div><div class=\"row one\"><div class=\"main\"><div class=\"bx visste\"><span class=\"rb\">Gemensamt för exemplen</span><p>I alla tre fallen fanns ett belägg från en undersökning som inte passade den gamla förklaringen. Men det tog tid att övertyga andra. Forskarvärlden vill ha belägg som kan granskas och upprepas, och helst en modell som förklarar <em>hur</em> det fungerar.</p></div></div></div><div class=\"kolla\"><span class=\"kr\">Kolla dig själv 1.2.2</span><ol><li>Vad visade Pasteurs svanhalskolv?</li><li>Vad var beläggen för Semmelweis idé?</li><li>Varför trodde många inte på honom?</li><li>Vad menas med att en modell är en förenkling? Ge ett exempel.</li></ol></div>", "fordjupning": "<p>I grundtexten mötte du Pasteur, Semmelweis samt Marshall och Warren. Nu ska vi jämföra dem och fråga varför det ibland tar så lång tid att ändra en förklaring.</p><table class=\"tbl\"><tr><th></th><th>Pasteur (1861)</th><th>Semmelweis (1847)</th><th>Marshall och Warren (1982)</th></tr><tr><td>Gammal förklaring</td><td>Små organismer kan uppstå av sig själva.</td><td>Barnsängsfeber har många orsaker, ingen tänker på händerna.</td><td>Magsår beror på stress och livsstil. Bakterier kan inte leva i magsyran.</td></tr><tr><td>Belägg</td><td>Buljong i svanhalskolv förblev klar, i rak kolv blev den grumlig.</td><td>Dödligheten på läkarkliniken föll från 11,4 % till 1,3 % efter handtvätt.</td><td>Bakterie i magsäcken. Marshalls självförsök 1984. Antibiotika botar.</td></tr><tr><td>Motstånd</td><td>Fick mothugg men kontrollerade försök övertygade.</td><td>Hånades. Saknade förklaring till hur. Fick inte förlängt kontrakt.</td><td>Marshall möttes av stark skepsis.</td></tr><tr><td>Vad övertygade?</td><td>Ett enkelt och upprepbart försök.</td><td>Bakterieläran växte fram årtionden senare.</td><td>Upprepade studier och en behandling som fungerade. Nobelpriset 2005.</td></tr></table><h3>Mönstret</h3><div class=\"row w\"><div class=\"main\"><p>I alla tre fall passade resultatet inte den förklaring som alla trodde på. Det är inte konstigt att forskare håller fast vid en modell som fungerat länge. En modell är en förenkling som har varit användbar, och en enstaka avvikelse kan bero på ett fel. Motståndet kan därför vara rimligt i början. Men när belägg samlas, från olika forskare och olika metoder, ändras bilden.</p><p>Det betyder inte att alla nya idéer har rätt. Marshall och Warren fick rätt för att de hade belägg som kunde granskas och upprepas, inte för att de var envisa.</p><h3>Modeller har begränsningar</h3><p>Ett exempel: bakterien <em>Helicobacter pylori</em> orsakar magsår, men långt ifrån alla som är smittade får magsår. Modellen ”bakterie orsakar magsår” är användbar, men inte hela förklaringen. Fler faktorer spelar in.</p></div><div class=\"side\"><div class=\"bx visste\"><span class=\"rb\">Lärdom</span><p>En bra modell förklarar vad man ser, förutsäger nya saker och kan prövas. Den behöver inte vara hela sanningen för att vara användbar.</p></div><div class=\"bx varning\"><span class=\"rb\">Etik</span><p>Marshalls självförsök var riskabelt. Forskning på människor måste granskas av en etikprövningsmyndighet.</p></div></div></div>"}, nivaStandard: "vanlig"};
innehall["biologi-m-1-2-3"] = {nivaer: {"lattlast": "<section class=\"sec m8\"><div class=\"lp\"><span class=\"p1\">LÄS</span><span class=\"t\">Delområde 1.2 · Moment 1.2.3</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">1.2.3 Söka information och bedöma källor</h2><div class=\"t\"><p>När du söker på nätet: använd flera sökord. Till exempel <em>sömn tonåringar forskning</em>.</p><p>En <strong>källa</strong> är där informationen kommer ifrån. <strong>Avsändaren</strong> är den som har skrivit eller gjort texten. Fråga dig:</p><p><strong>Trovärdig</strong> betyder att man kan lita på den. <strong>Relevant</strong> betyder att den passar din fråga.</p><div class=\"fig\"><img src=\"bilder/biologi-omrade1/l_fyra.png\"></div><p>Fråga också: Finns det <strong>belägg</strong>? Reklam har ofta inga belägg. Den vill sälja.</p><table class=\"tb\"><tr><th>Fråga om källan</th><th>Bra tecken</th></tr><tr><td>Vem har skrivit?</td><td>Forskare, myndighet eller en känd organisation</td></tr><tr><td>Varför är det skrivet?</td><td>Att informera. Inte att sälja</td></tr><tr><td>Finns det belägg?</td><td>Mätningar, undersökningar eller länkar till forskning</td></tr><tr><td>Är det nytt?</td><td>Skrivet för inte så länge sedan</td></tr><tr><td>Säger andra källor samma sak?</td><td>Ja, minst två till</td></tr></table><div class=\"arg\"><b class=\"h\">SÅ ARGUMENTERAR DU</b>1. <b>Påstående:</b> Jag tycker att …<br>2. <b>Belägg:</b> Jag tycker det eftersom …<br>3. <b>Motargument:</b> Någon kan säga att … Men …<br>4. <b>Slutsats:</b> Alltså …</div></div><div class=\"kom\"><span class=\"ex\">!</span><div><span class=\"lb\">KOM IHÅG</span><span class=\"tx\">Fråga: vem, varför, belägg, när och fler källor. Då ser du om en källa går att lita på.</span></div></div></section><section class=\"sec m8\"><div class=\"lp\"><span class=\"p1 ova\">ÖVA</span><span class=\"t\">Delområde 1.2 · Moment 1.2.3</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"\"></i></span></div><h2 class=\"lh\">Öva: 1.2.3 Söka information och bedöma källor</h2><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">1</span><div><span class=\"ty\">DRA STRECK</span><span class=\"q\">Vilken fråga passar? Dra streck.</span><div class=\"dr\"><div>Vem?</div><div>Står det på fler ställen?</div><div>Varför?</div><div>Vem har skrivit texten?</div><div>När?</div><div>Vill de sälja något?</div><div>Fler källor?</div><div>Är texten gammal?</div></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">2</span><div><span class=\"ty\">RINGA IN</span><span class=\"q\">Reklamen säger: ”Superbär botar ALLT på en dag!” Vad tror du?</span><div class=\"chips\"><span>Det är sant</span><span>Det är nog inte sant</span></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">3</span><div><span class=\"ty\">FYLL I</span><span class=\"q\">Skriv rätt ord på linjen.</span><span class=\"bank\">Ord att välja: trovärdig · relevant · belägg</span><div class=\"fy\"><p>En källa som går att lita på är ______________.</p><p>En källa som passar min fråga är ______________.</p><p>Mätningar som visar något kallas ______________.</p></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">4</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Hur kan du se om en webbsida går att lita på?</span><div class=\"ln\">Jag kan<i></i><i></i></div></div></div></div></section>", "vanlig": "<p>Varje dag möter du påståenden om hälsa, mat, djur och miljö: i sociala medier, reklam, nyheter och samtal. Att söka bra information börjar med att använda flera sökord, till exempel <em>sömn tonåringar forskning</em>, och att jämföra flera källor. Sedan måste du bedöma källorna.</p><table class=\"tbl\"><tr><th>Typ av källa</th><th>Exempel</th><th>Styrka</th><th>Se upp med</th></tr><tr><td>Myndighet</td><td>Folkhälsomyndigheten, Naturvårdsverket, 1177</td><td>Faktagranskad, oberoende</td><td>Kan vara allmänt hållen</td></tr><tr><td>Forskning</td><td>Universitet, vetenskaplig artikel</td><td>Granskad av andra experter</td><td>En enda studie räcker inte. Kan vara svår att läsa</td></tr><tr><td>Nyhetsmedia</td><td>Tidningar, tv</td><td>Snabb och lättläst</td><td>Rubriker kan vara vinklade</td></tr><tr><td>Sociala medier</td><td>Inlägg, videor</td><td>Kan peka ut nya idéer</td><td>Ofta ogranskat. Berättelser är inte belägg</td></tr><tr><td>Reklam och företag</td><td>Webbplats för en produkt</td><td>Känner sin produkt</td><td>Vill sälja. Tendens</td></tr></table><h3>Trovärdig och relevant</h3><p>En källa är <strong class='green'>trovärdig</strong> om man kan lita på den. En källa är <strong class='green'>relevant</strong> om den passar din fråga. En trovärdig källa kan vara irrelevant: en studie om möss säger inte nödvändigtvis något om människor. Fyra frågor brukar kallas de källkritiska kriterierna:</p><div class=\"cards\" style=\"grid-template-columns:repeat(4,1fr)\"><div class=\"card\"><b class=\"h\">Äkthet</b>Är källan den den utger sig för att vara? Är bilden eller citatet äkta?</div><div class=\"card\"><b class=\"h\">Tid</b>När skrevs det? Är informationen fortfarande aktuell?</div><div class=\"card\"><b class=\"h\">Beroende</b>Var kommer uppgifterna ifrån? Har avsändaren själv undersökt, eller bara hört från någon annan?</div><div class=\"card\"><b class=\"h\">Tendens</b>Vill avsändaren något: sälja, övertyga eller påverka? Visas flera sidor?</div></div><div class=\"fig\" style=\"width:70%\"><img src=\"bilder/biologi-omrade1/v_inlagg.png\"><div class=\"cap\"><b>Bild 1.9</b> Ett påhittat inlägg i sociala medier, granskat med de källkritiska kriterierna.</div></div><h3>Argumentera</h3><div class=\"row w\"><div class=\"main\"><p>När du har granskat källorna ska du kunna använda dem. Ett bra argument har ett <strong class='green'>påstående</strong>, ett <strong class='green'>belägg</strong> och ett svar på ett <strong class='green'>motargument</strong>.</p><p><b>Exempel:</b> <em>Skolor bör ha rutiner för handtvätt före lunch. Handtvätt minskar spridning av infektioner, vilket Semmelweis exempel visar. Någon kan säga att det tar tid. Men tiden är liten jämfört med de dagar elever är sjuka.</em></p></div><div class=\"side\"><div class=\"bx tank\"><span class=\"rb\">Så argumenterar du</span><p>1. Påstående<br>2. Belägg (varför?)<br>3. Motargument (vad kan någon säga emot?)<br>4. Bemöt det<br>5. Slutsats</p></div></div></div><div class=\"kolla\"><span class=\"kr\">Kolla dig själv 1.2.3</span><ol><li>Vad är skillnaden mellan trovärdig och relevant?</li><li>Varför är reklam en källa man ska vara försiktig med?</li><li>Granska ett påstående med hjälp av de fyra kriterierna.</li><li>Skriv ett kort argument om ett eget påstående, med belägg och motargument.</li></ol></div>", "fordjupning": "<p>Ibland säger trovärdiga källor emot varandra. Då räcker det inte att fråga om en källa är trovärdig. Man måste väga dem mot varandra: Vilken bygger på flest och bäst undersökningar? Vem har gjort studien, och vem har betalat för den? Finns det en oberoende upprepning?</p><div class=\"cards\" style=\"grid-template-columns:repeat(4,1fr)\"><div class=\"card\"><b class=\"h\">Oberoende</b>Har källan undersökt själv eller bara hört av andra? Går uppgifterna att följa tillbaka?</div><div class=\"card\"><b class=\"h\">Tendens</b>Vem tjänar på budskapet? Vem betalade för undersökningen?</div><div class=\"card\"><b class=\"h\">Samsyn</b>Säger andra, oberoende källor samma sak? Vad säger sammanställningar?</div><div class=\"card\"><b class=\"h\">Aktualitet</b>Är det nytt nog? Har nyare studier ändrat bilden?</div></div><h3>Läs diagram och statistik med kritiskt öga</h3><div class=\"row w\"><div class=\"main\"><p><strong>Korrelation är inte orsak.</strong> När glassförsäljningen ökar, ökar också antalet drunkningsolyckor. Båda beror på en tredje sak: värmen.</p><p><strong>Avkortad axel.</strong> Om y-axeln börjar på 90 i stället för 0 ser en liten skillnad enorm ut.</p><p><strong>Relativ ökning.</strong> ”Risken dubblas!” kan betyda att den går från 1 på 100 000 till 2 på 100 000. Fråga alltid efter hur stor risken var från början.</p><p><strong>Sponsring och tendens.</strong> En studie betald av ett företag är inte automatiskt fel, men man bör se om den är oberoende granskad och om andra har fått samma resultat.</p></div><div class=\"side\"><div class=\"fig\"><img src=\"bilder/biologi-omrade1/v_glass.png\"><div class=\"cap\"><b>Bild F1.3</b> Två kurvor som följer varandra utan att den ena orsakar den andra.</div></div></div></div><h3>Bemöt motargument</h3><div class=\"row\"><div class=\"main\"><p>Ett starkt argument tar motargumentet på allvar. Skriv påstående, belägg, det starkaste motargumentet och ett svar som visar varför beläggen ändå väger tyngre, eller var du kan hålla med. Avsluta med en slutsats som säger hur säker du är.</p></div><div class=\"side\"><div class=\"bx tank\"><span class=\"rb\">Tänk efter</span><p>En tidning skriver: ”Studie: Kaffe förlänger livet!” Vilka tre frågor ställer du innan du tror på det?</p></div></div></div>"}, nivaStandard: "vanlig"};
innehall["biologi-m-1-2-l"] = {nivaer: {"lattlast": "<section class=\"sec m9\"><div class=\"lp\"><span class=\"p1\">LABB</span><span class=\"t\">Delområde 1.2 · Labb (45 min)</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i></span></div><h2 class=\"lh\">Labb 1.2 Granska ett påstående</h2><div class=\"t\"><p><strong>Fråga:</strong> Är påståendet sant? Du ska granska det med hjälp av två källor.</p><p>Välj ett påstående:</p><ol class='st'><li>Tio procent av hjärnan används.</li><li>Socker gör barn hyperaktiva.</li><li>Blixten slår aldrig ned två gånger på samma plats.</li></ol><ol class='st'><li>Sök efter påståendet. Hitta två olika källor.</li><li>Fyll i checklistan för varje källa.</li><li>Bestäm: Är påståendet sant, osant eller osäkert?</li><li>Skriv ett kort argument. Använd mallen.</li></ol><div class=\"arg\"><b class=\"h\">SÅ ARGUMENTERAR DU</b>1. <b>Påstående:</b> Jag tycker att …<br>2. <b>Belägg:</b> Jag tycker det eftersom …<br>3. <b>Motargument:</b> Någon kan säga att … Men …<br>4. <b>Slutsats:</b> Alltså …</div><p><strong>Säkerhet:</strong> Skriv inga personuppgifter. Klicka inte på reklam eller länkar du inte litar på.</p></div><div class=\"kom\"><span class=\"ex\">!</span><div><span class=\"lb\">KOM IHÅG</span><span class=\"tx\">Granska varje källa. Svara sedan med påstående, belägg, motargument och slutsats.</span></div></div></section><section class=\"sec m9\"><div class=\"lp\"><span class=\"p1 ova\">ÖVA</span><span class=\"t\">Delområde 1.2 · Labb (45 min)</span><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i></span></div><h2 class=\"lh\">Öva: Labb 1.2 Granska ett påstående</h2><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">1</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Källa 1: Skriv webbadress eller namn. Svara sedan: vem har skrivit? Är den trovärdig?</span><div class=\"ln\"><p>Källa 1:<i></i></p><p>Trovärdig? Varför?<i></i></p></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">2</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Källa 2: Skriv webbadress eller namn. Svara sedan: vem har skrivit? Är den trovärdig?</span><div class=\"ln\"><p>Källa 2:<i></i></p><p>Trovärdig? Varför?<i></i></p></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">3</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Skriv ditt argument.</span><div class=\"ln\"><p>Mitt påstående:<i></i></p><p>Belägg:<i></i></p><p>Motargument och svar:<i></i></p><p>Slutsats:<i></i></p></div></div></div></div></section>", "vanlig": "<p>Du ska granska ett påstående med hjälp av två källor och skriva ett argument med belägg och motargument. Arbetet tar 45 minuter. Välj ett påstående:</p><ul class=\"pu\"><li>Vi använder bara tio procent av hjärnan.</li><li>Socker gör barn hyperaktiva.</li><li>Blixten slår aldrig ned två gånger på samma plats.</li></ul><div class=\"row w\"><div class=\"main\"><h3 style='margin-top:0'>Gör så här</h3><ol class=\"steps\"><li>Sök efter påståendet med flera sökord. Hitta två källor av olika typ, till exempel en myndighet och en tidning.</li><li>Bedöm varje källa: äkthet, tid, beroende och tendens. Är den trovärdig? Är den relevant?</li><li>Bestäm om påståendet är sant, osant eller osäkert, och skriv varför.</li><li>Skriv ett argument: påstående, belägg, motargument, bemötande, slutsats.</li></ol></div><div class=\"side\"><table class=\"tbl num\"><tr><th>Fråga</th><th>Källa 1</th><th>Källa 2</th></tr><tr><td>Vem har skrivit?</td><td></td><td></td></tr><tr><td>Varför?</td><td></td><td></td></tr><tr><td>Belägg?</td><td></td><td></td></tr><tr><td>Hur nytt?</td><td></td><td></td></tr><tr><td>Trovärdig?</td><td></td><td></td></tr></table><div class=\"bx tank\"><span class=\"rb\">Utvärdera</span><p>Vilken källa litar du mest på? Varför? Hur kan två trovärdiga källor säga olika?</p></div></div></div><p class=\"note\">Säkerhet: skriv inga personuppgifter och klicka inte på reklam eller länkar du inte litar på.</p>"}, nivaStandard: "vanlig"};
innehall["biologi-m-1-s"] = {nivaer: {"lattlast": "<section class=\"sec\"><div class=\"sh\"><h2>Viktiga ord</h2></div><p>Läs orden och titta på bilderna. Du kan komma tillbaka hit när du läser.</p><div class=\"ord2\"><div><b>biologi</b>läran om allt som lever</div><div><b>organism</b>allt som lever, till exempel djur, växter och bakterier</div><div><b>undersökningsbar fråga</b>en fråga du kan svara på genom att mäta eller titta</div><div><b>hypotes</b>det man tror blir svaret, och varför</div><div><b>variabel</b>något som kan ändras eller mätas</div><div><b>rättvist test</b>man ändrar bara en sak. Allt annat är lika</div><div><b>tabell</b>ett sätt att skriva ner det man mäter</div><div><b>diagram</b>en bild av siffror, till exempel staplar</div><div><b>resultat</b>det man mäter eller ser</div><div><b>slutsats</b>det man lär sig av resultatet</div><div><b>felkälla</b>något som kan göra att resultatet blir fel</div><div><b>slump</b>något som händer av en tillfällighet</div><div><b>påstående</b>något man säger är sant</div><div><b>belägg</b>mätningar eller observationer som visar något</div><div><b>åsikt</b>vad någon tycker. Går inte att mäta</div><div><b>pseudovetenskap</b>låter som vetenskap men saknar belägg</div><div><b>modell</b>ett sätt att förklara hur något fungerar</div><div><b>mikroorganism</b>en mycket liten organism, till exempel en bakterie</div><div><b>källa</b>där informationen kommer ifrån</div><div><b>trovärdig</b>går att lita på</div><div><b>relevant</b>passar min fråga</div><div><b>avsändare</b>den som har skrivit eller gjort texten</div></div></section><section class=\"sec\"><div class=\"sh\"><h2>Det viktigaste</h2></div><p>Här är allt det viktigaste i kapitlet. Läs det en gång till.</p><div class=\"vik\"><img src=\"bilder/biologi-omrade1/l_ic1.png\"><span>Biologi är läran om allt som lever.</span></div><div class=\"vik\"><img src=\"bilder/biologi-omrade1/l_ic2.png\"><span>Forskare frågar, gissar (hypotes), testar och svarar (slutsats).</span></div><div class=\"vik\"><img src=\"bilder/biologi-omrade1/l_ic3.png\"><span>I ett rättvist test ändrar man bara en sak.</span></div><div class=\"vik\"><img src=\"bilder/biologi-omrade1/l_ic4.png\"><span>Resultatet är det man mäter. Slutsatsen är det man lär sig.</span></div><div class=\"vik\"><div></div><span>Resultatet kan bli fel. Gör om testet och skriv vad som kan ha blivit fel.</span></div><div class=\"vik\"><div></div><span>Vetenskap prövar påståenden med belägg. Åsikter går inte att pröva.</span></div><div class=\"vik\"><div></div><span>En modell kan ändras när nya undersökningar visar något annat.</span></div><div class=\"vik\"><img src=\"bilder/biologi-omrade1/l_ic6.png\"><span>Tro inte på allt du läser. Kolla vem, varför, belägg, när och fler källor.</span></div></section>", "vanlig": "<section class=\"sec\"><div class=\"sh\"><h2>Sammanfattning</h2></div><div class=\"sam\"><ul><li><strong>Biologi</strong> är läran om livet. Biologer arbetar i fält, i labb och vid datorer.</li><li>En <strong>undersökningsbar fråga</strong> går att besvara med mätningar. En <strong>hypotes</strong> är ett prövbart svar med motivering.</li><li>I ett rättvist försök ändrar man en <strong>oberoende variabel</strong>, mäter en <strong>beroende variabel</strong> och håller alla andra lika. En kontrollgrupp ger något att jämföra med.</li><li>Värden skrivs i tabell med rubriker och enheter. Diagram har rubrik och axlar med namn och enhet. Man räknar medelvärde av upprepningar.</li><li>Resultat kan bli fel av slump eller systematiska fel. Upprepning minskar slumpens betydelse. Slutsatsen ska svara på frågan och stämma med resultatet.</li><li>Vetenskap prövar påståenden med belägg. Åsikter och tro går inte att pröva med mätningar. Pseudovetenskap saknar prövade belägg.</li><li>Förklaringsmodeller ändras när nya belägg kommer: Pasteur, Semmelweis, Marshall och Warren.</li><li>Bedöm källor med äkthet, tid, beroende och tendens. Skilj trovärdig från relevant. Ett argument har påstående, belägg och bemötande av motargument.</li></ul></div><h3>Viktiga begrepp</h3><div class=\"begr\"><div><b>Belägg</b>Observationer och mätningar som stöder en slutsats.</div><div><b>Beroende variabel</b>Det man mäter i en undersökning.</div><div><b>Felkälla</b>Något som kan ha påverkat resultatet utan att man ville det.</div><div><b>Förklaringsmodell</b>Ett sätt att förklara hur något fungerar.</div><div><b>Giltighet</b>Om man har mätt det man ville undersöka.</div><div><b>Hypotes</b>Ett möjligt, prövbart svar på en fråga.</div><div><b>Kontrollgrupp</b>Grupp där man inte ändrar något, att jämföra med.</div><div><b>Kontrollerade variabler</b>Det som hålls lika för att testet ska bli rättvist.</div><div><b>Medelvärde</b>Summan av värdena delat med antalet.</div><div><b>Oberoende variabel</b>Det man själv ändrar i en undersökning.</div><div><b>Pseudovetenskap</b>Låter vetenskapligt men saknar prövade belägg.</div><div><b>Relevant</b>Passar min fråga.</div><div><b>Slump</b>Tillfälliga variationer som inte beror på det man undersöker.</div><div><b>Teori</b>En väl prövad förklaring som stöds av många belägg.</div><div><b>Tillförlitlighet</b>Hur säkra och upprepbara mätningarna är.</div><div><b>Trovärdig</b>Går att lita på.</div><div><b>Undersökningsbar fråga</b>Kan besvaras med mätningar eller observationer.</div></div></section>"}, nivaStandard: "vanlig"};
innehall["biologi-m-1-t"] = {nivaer: {"lattlast": "<section class=\"sec\"><div class=\"sh\"><h2>Testa dig själv</h2></div><p>Nu får du visa vad du har lärt dig. Du kan titta i kapitlet om du vill.</p><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">1</span><div><span class=\"ty\">RINGA IN</span><span class=\"q\">Vem forskar om växter?</span><div class=\"chips\"><span>Botaniker</span><span>Zoolog</span><span>Marinbiolog</span></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">2</span><div><span class=\"ty\">DRA STRECK</span><span class=\"q\">Dra streck till rätt förklaring.</span><div class=\"dr\"><div>Hypotes</div><div>det man lär sig</div><div>Resultat</div><div>det man mäter eller ser</div><div>Slutsats</div><div>det man tror blir svaret, och varför</div><div>Belägg</div><div>mätningar som visar något</div></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">3</span><div><span class=\"ty\">SANT ELLER FALSKT</span><span class=\"q\">Kryssa i rätt ruta.</span><div class=\"sf\"><table><tr><th></th><th>Sant</th><th>Falskt</th></tr><tr><td>I ett rättvist test ändrar man många saker.</td><td class=\"c\"><b class=\"bx\"></b></td><td class=\"c\"><b class=\"bx\"></b></td></tr><tr><td>Man får äta i labbet.</td><td class=\"c\"><b class=\"bx\"></b></td><td class=\"c\"><b class=\"bx\"></b></td></tr><tr><td>Man kan inte pröva en åsikt med mätningar.</td><td class=\"c\"><b class=\"bx\"></b></td><td class=\"c\"><b class=\"bx\"></b></td></tr><tr><td>Allt som står på nätet är sant.</td><td class=\"c\"><b class=\"bx\"></b></td><td class=\"c\"><b class=\"bx\"></b></td></tr></table></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">4</span><div><span class=\"ty\">RINGA IN</span><span class=\"q\">Vilken fråga går att undersöka?</span><div class=\"chips\"><span>Är hundar snälla?</span><span>Hur högt hoppar en groda?</span><span>Är sommar bäst?</span></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">5</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Du vill testa om bönor gror bäst i varmt eller kallt. Vad ska du ändra? Vad ska vara lika?</span><div class=\"ln\"><p>Jag ändrar<i></i></p><p>Det här ska vara lika:<i></i></p></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">6</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Ali säger: ”Mina bönor i värmen grodde snabbast. Alltså gror alla bönor bäst i värme.” Vad borde Ali göra för att vara säkrare?</span><div class=\"ln\">Ali borde<i></i><i></i></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">7</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">Semmelweis fick läkarna att tvätta händerna. Vad hände med dödligheten?</span><div class=\"ln\">Dödligheten<i></i></div></div></div></div><div class=\"ex1\"><div class=\"hd\"><span class=\"no\">8</span><div><span class=\"ty\">SKRIV</span><span class=\"q\">En webbsida säger att ett te botar förkylning på en timme. Hur kan du ta reda på om det stämmer?</span><div class=\"ln\">Jag kan<i></i><i></i></div></div></div></div></section>", "vanlig": "<section class=\"sec\"><div class=\"sh\"><h2>Testa dig själv</h2></div><p class=\"note\">Uppgifterna liknar uppgifterna i nationella prov i biologi. Personer, annonser och mätvärden är påhittade. ● grundläggande &nbsp;●● utvecklat &nbsp;●●● välutvecklat</p><div class=\"pill\">Del A · VÄLJ ETT ALTERNATIV</div><div class=\"q\"><span class=\"n\">1</span><div>Elin undersöker om temperaturen påverkar hur mycket gas jäst bildar. Hon mäter mängden gas efter 20 minuter. Vilken är den beroende variabeln?<div class=\"alts\"><div>A Temperaturen</div><div>B Mängden gas</div><div>C Mängden jäst</div><div>D Tiden, 20 minuter</div></div></div><span class=\"pts\">●</span></div><div class=\"q\"><span class=\"n\">2</span><div>Vilket påstående går att pröva med naturvetenskapliga metoder?<div class=\"alts one\"><div>A Blåbär smakar godare än lingon.</div><div>B Krasse gror snabbare vid 20 °C än vid 10 °C.</div><div>C Det är fel att jaga varg.</div><div>D Naturen vill alltid vara i balans.</div></div></div><span class=\"pts\">●</span></div><div class=\"q\"><span class=\"n\">3</span><div>Vad visade att handtvätt hjälpte på Semmelweis avdelning?<div class=\"alts one\"><div>A Läkarna blev tröttare.</div><div>B Dödligheten sjönk från 11,4 % till 1,3 %.</div><div>C Barnmorskorna slutade arbeta.</div><div>D Fler kvinnor kom till sjukhuset.</div></div></div><span class=\"pts\">●</span></div><div class=\"pill\">Del B · SVARA KORT</div><div class=\"q\"><span class=\"n\">4</span><div>Förklara varför man upprepar ett försök flera gånger och räknar ut ett medelvärde.<div class=\"lines\"><i></i><i></i><i></i></div></div><span class=\"pts\">●●</span></div><div class=\"q\"><span class=\"n\">5</span><div>Förklara skillnaden mellan en trovärdig och en relevant källa. Ge ett exempel.<div class=\"lines\"><i></i><i></i><i></i></div></div><span class=\"pts\">●●</span></div><div class=\"pill\">Del C · PLANERA EN UNDERSÖKNING</div><div class=\"q\"><span class=\"n\">6</span><div>Noah vill ta reda på om gödning påverkar hur mycket ärtplantor växer. Han har ärtfrön, krukor, jord, vatten, flytande gödning och en linjal. Planera undersökningen. Skriv<br>a) en frågeställning och en hypotes,<br>b) oberoende och beroende variabel,<br>c) minst tre variabler som ska hållas lika. ●●●<div class=\"lines\"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><span class=\"pts\">●●●</span></div><div class=\"q\"><span class=\"n\">7</span><div>Mira vill ta reda på om temperaturen påverkar hur snabbt bönor gror. Hon sätter bönor i en burk med fuktigt papper i ett soligt fönster och bönor i en annan burk i kylskåpet.<br>a) Ge ett skäl till att Miras undersökning inte blir rättvis.<br>b) Föreslå en förbättring. ●●<div class=\"lines\"><i></i><i></i><i></i><i></i><i></i></div></div><span class=\"pts\">●●</span></div><div class=\"pill\">Del E · GRANSKA INFORMATION</div><div class=\"q\"><span class=\"n\">8</span><div>Läs annonsen och svara.<div class=\"fakeann\"><span class=\"fake\">Påhittad annons</span></div><div style=\"border:1pt solid #d9d2c8;border-radius:5pt;padding:5pt 8pt;margin:3pt 0\"><b>NYHET! DetoxPlåstret™</b><br>Sätt plåstret under foten när du sover – på morgonen har det blivit brunt av alla gifter som dragits ut ur kroppen! ”Jag har aldrig mått så bra”, säger Anna, 34. Vetenskapligt utvecklat.</div>a) Använd de källkritiska kriterierna. Ge två skäl till att vara skeptisk.<br>b) Hur skulle man kunna undersöka om plåstret verkligen drar ut gifter? ●●●<div class=\"lines\"><i></i><i></i><i></i><i></i><i></i></div></div><span class=\"pts\">●●●</span></div><div class=\"pill\">Del F · RESONERA</div><div class=\"q\"><span class=\"n\">9</span><div>Välj ett av exemplen Pasteur, Semmelweis eller Marshall och Warren. Förklara hur förklaringen ändrades när nya belägg kom, och varför det tog tid att övertyga andra. ●●<div class=\"lines\"><i></i><i></i><i></i><i></i><i></i></div></div><span class=\"pts\">●●</span></div></section>", "fordjupning": "<section class=\"sec\"><div class=\"sh\"><h2>Resonera och ta ställning</h2></div><p class=\"note\">Uppgifterna liknar de svåraste uppgifterna på nationella prov. Personer, rubriker och mätvärden är påhittade. Svara utförligt och resonera i flera led. ● grundläggande &nbsp;●● utvecklat &nbsp;●●● välutvecklat</p><div class=\"q\" style=\"break-inside:avoid;grid-template-columns:16pt minmax(0,1fr) 34pt\"><span class=\"n\">1</span><div>Ett företag påstår att deras sportdryck ger bättre kondition. Planera en undersökning som kan pröva påståendet. Beskriv hur du använder kontrollgrupp, placebo, randomisering och blindning, och förklara varför varje del behövs.<div class=\"lines\"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><span class=\"pts\">●●●</span></div><div class=\"q\" style=\"break-inside:avoid;grid-template-columns:16pt minmax(0,1fr) 34pt\"><span class=\"n\">2</span><div>Semmelweis jämförde två avdelningar. Förklara varför jämförelsen gjorde hans slutsats starkare, och ge ett skäl till att hans slutsats ändå inte var helt säker innan handtvätten infördes.<div class=\"lines\"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><span class=\"pts\">●●●</span></div><div class=\"q\" style=\"break-inside:avoid;grid-template-columns:16pt minmax(0,1fr) 34pt\"><span class=\"n\">3</span><div>En tidning skriver: ”Ny studie: Kaffe gör att du lever längre! Forskare har följt 500 000 personer och de som drack 2–3 koppar om dagen dog i lägre grad.” Värdera rubriken med begreppen observationsstudie, störfaktor och orsakssamband. Vad skulle krävas för att man säkert kan säga att kaffet är orsaken?<div class=\"lines\"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><span class=\"pts\">●●●</span></div></section><section class=\"sec\"><div class=\"sh\"><h2>Resonera och ta ställning, forts.</h2></div><div class=\"q\" style=\"break-inside:avoid;grid-template-columns:16pt minmax(0,1fr) 34pt\"><span class=\"n\">4</span><div>Två klasser testar om gödning gör att bönplantor växer högre. Klass A har 3 plantor per grupp och får skillnaden 4 mm. Klass B har 30 plantor per grupp och får skillnaden 2 mm. Vilket resultat litar du mest på? Motivera och diskutera slumpens betydelse.<div class=\"lines\"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><span class=\"pts\">●●</span></div><div class=\"q\" style=\"break-inside:avoid;grid-template-columns:16pt minmax(0,1fr) 34pt\"><span class=\"n\">5</span><div>Tabellen om jäst (F1.1.2) har ett avvikande värde vid 40 °C. Förklara hur du hanterar det och hur du redovisar resultatet så att läsaren kan avgöra hur säker slutsatsen är.<div class=\"lines\"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><span class=\"pts\">●●●</span></div><div class=\"q\" style=\"break-inside:avoid;grid-template-columns:16pt minmax(0,1fr) 34pt\"><span class=\"n\">6</span><div>Jämför två av exemplen Pasteur, Semmelweis och Marshall och Warren. Vad är gemensamt, och vad skiljer dem åt? Resonera om varför nya idéer ibland möts av motstånd, och om motståndet alltid är oberättigat.<div class=\"lines\"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><span class=\"pts\">●●●</span></div><div class=\"q\" style=\"break-inside:avoid;grid-template-columns:16pt minmax(0,1fr) 34pt\"><span class=\"n\">7</span><div>Två trovärdiga källor säger olika om ett kosttillskott: en myndighet avråder, en studie betald av tillverkaren visar effekt. Resonera om hur du väger källorna och vilken ytterligare information du skulle vilja ha. Formulera ett argument och bemöt ett motargument.<div class=\"lines\"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><span class=\"pts\">●●●</span></div></section>"}, nivaStandard: "vanlig"};
